function prepare_all(){const imageThumbLoader=window.imageThumbLoader;let body=$('body');isMobile()&&body.addClass('mobile');isIOS()&&body.addClass('ios');isAndroid()&&body.addClass('android');handleResize();$(window).on('resize',debounce(handleResize,250));let lazyLoadRafId=null;$(window).on('scroll resize',function(){if(lazyLoadRafId!==null)return;lazyLoadRafId=requestAnimationFrame(function(){lazyLoadRafId=null;imageThumbLoader.startLazyLoad()})});initFormsGroup(body,imageThumbLoader);initSearchAndFilters(body,imageThumbLoader);initCommonActions(body);initMedia();initTextExpand();initFeedAndLive(body,imageThumbLoader)}
function initFormsGroup(body,imageThumbLoader){addFormValidation();function addFormValidation(){const forms=document.querySelectorAll('.needs-validation');forms.forEach((form)=>{form.addEventListener('submit',(event)=>{form.classList.add('was-validated');if(!form.checkValidity()){event.preventDefault();if(typeof event.stopImmediatePropagation==='function'){event.stopImmediatePropagation()}else{event.stopPropagation()}
const firstInvalid=form.querySelector(':invalid');if(firstInvalid){try{firstInvalid.focus({preventScroll:!0})}catch(e){firstInvalid.focus()}
firstInvalid.scrollIntoView({behavior:'smooth',block:'center'})}}},!1)})}
$('#describe').on('change keyup keydown',function(){if($(this).val()!==encodeURIComponent($(this).val())){$(this).attr('maxlength',500)}else{$(this).attr('maxlength',2500)}
$(this).val($(this).val().substring(0,$(this).attr('maxlength')))});$('#name').on('change keyup keydown',function(){if($(this).val()!==encodeURIComponent($(this).val())){$(this).attr('maxlength',50)}else{$(this).attr('maxlength',256)}
$(this).val($(this).val().substring(0,$(this).attr('maxlength')))});if(0===$('.splash-18').length){imageThumbLoader.startLazyLoad()}}
function initSearchAndFilters(body,imageThumbLoader){let performer_search_suggest=$('.js-performer-search-suggest');if(performer_search_suggest.length>0){performer_search_suggest.on('keyup',function(event){performers_search(event,'performer_search_suggest_apply')});performer_search_suggest.on('keydown',performer_search_suggest_keynav);performer_search_suggest.on('click',function(){let search_box_result_block=$(this).closest('.search-box').find('.search-box-result');if(search_box_result_block.children().length>0){search_box_result_block.show()}});body.on('click',function(e){if($(e.target).closest(".search-box-result").length===0){$(".search-box-result").hide()}});body.on('mousemove','.search-box-result .performer-li > a.dropdown-item',function(){const $item=$(this);const $resultBlock=$item.closest('.search-box-result');$resultBlock.removeClass('keynav-active');if($item.hasClass('active'))return;$resultBlock.find('.performer-li > a.dropdown-item.active').removeClass('active');$item.addClass('active')});body.on('mouseleave','.search-box-result',function(){const $resultBlock=$(this);$resultBlock.removeClass('keynav-active');$resultBlock.find('.performer-li > a.dropdown-item.active').removeClass('active')})}
if($('#tag_search_suggest').length>0){$('#tag_search_suggest').on('keyup',function(event){tags_search(event,'performer_search_suggest_apply')});$('#tag_search_suggest').on('click',function(){if($(".search-box-result").children().length>0){$(".search-box-result").show()}});body.on('click',function(e){if($(e.target).closest(".search-box-result").length===0){$(".search-box-result").hide()}})}
if(isMobile()){let containerWidth=$('body .container').width();if(containerWidth<=510){$('.filter-country .dropdown-menu').css('width',containerWidth)}}
let filterSelect=$('.filter-select');filterSelect.each(function(){const applySearch=function(filterValue,items){items.each(function(){let item=$(this);if(item.text().toLowerCase().includes(filterValue.toLowerCase())){item.show()}else{item.hide()}});if(items.filter(':visible').length===0){filterSelect.find('.no-results').show()}else{filterSelect.find('.no-results').hide()}}
let input=$(this).find('input');let clearButton=$(this).find('.js-item-search-clear');let items=$(this).find('.item-li');let filterValue=input.val().trim();if(filterValue!==''){applySearch(filterValue,items)}
input.on('keyup input',function(){if($(this).val().trim()!==''){$(this).closest('.dropdown-menu').addClass('searching')}else{$(this).closest('.dropdown-menu').removeClass('searching')}
applySearch($(this).val().trim(),items)});clearButton.on('click',function(e){e.stopPropagation();e.preventDefault();input.val('').trigger('input')})})
body.find('[data-cevent]').on('click',function(){let data={event:$(this).data('cevent'),link:$(this).data('redirecturl')};EventTracker.save(data)});if($('#recentVideoFilter').length>0){let videoFilterParams=new URLSearchParams(window.location.search);if(videoFilterParams.has('type')){let videoFilterParamType=videoFilterParams.get('type')
let videoFilterBtn=$('#recentVideoFilter .filter-type .btn[data-type="'+videoFilterParamType+'"]');if(videoFilterBtn.length>0){videoFilterBtn.siblings().removeClass('active');videoFilterBtn.addClass('active')}}
let $periodDropdownRoot=$('.filter-period-dropdown');if($periodDropdownRoot.length>0&&typeof bootstrap!=='undefined'){let $periodDropends=$periodDropdownRoot.find('.dropend');$periodDropdownRoot.on('show.bs.dropdown',function(e){let $currentDropend=$(e.target).closest('.dropend');if($currentDropend.length===0)return;$periodDropends.each(function(){let $dropend=$(this);if($dropend.is($currentDropend))return;let trigger=$dropend.find('[data-bs-toggle="dropdown"]').get(0);if(trigger){let instance=bootstrap.Dropdown.getInstance(trigger);if(instance)instance.hide();}})})}}}
function initCommonActions(body){function toggleBlur(isOn){body.toggleClass('blur-enabled',isOn)}
let blurElement=$('#blur');if(blurElement.length){if(localStorage.getItem('blur')!==null){blurElement.prop("checked",localStorage.getItem('blur')==='true')}
toggleBlur(blurElement.prop("checked"))}
blurElement.click(function(){localStorage.setItem('blur',this.checked);toggleBlur(this.checked)});body.on('click','.show-more-videos',function(){$(this).hide();$(this).siblings('.hidden-videos').show()});$('.util-require-change').each(function(){function enable(){$submit.attr('disabled',!1).attr('title','')}
function disable(){$submit.attr('disabled',!0).attr('title',disabledTitle)}
const $this=$(this),initVal=$this.val(),$submit=$this.parents('form').find('button[type=submit]'),disabledTitle=$this.data('disabled-submit-title')??'Change form values to submit';disable();if(initVal!==undefined){$this.on('keyup change',function(){if($(this).val()!==initVal){enable()}else{disable()}})}});body.on('click','.g-event',function(){let gevent=$(this).data('gevent')??'click';let event=$(this).data('event')??'click';let type=$(this).data('type')??'button';gtag('event',gevent,{'event':event,'type':type,})})}
function initMedia(){$('.performer-overview .slider').each(function(idx,event){const $slider=$(event);new VideoThumbSlider($slider,{elements:$slider.data('elements')||3,stepColumns:$slider.data('step')||null,addPlayNow:!1,})})}
function initTextExpand(){function updateTextExpandToggle(){$('[data-text-expand-item]').each(function(){const $item=$(this);const $text=$item.find('[data-text-expand-content]');const $more=$item.find('[data-text-expand-toggle]');if(!$text.length||!$more.length)return;const isOpen=$item.hasClass('text-expand-open');if(isOpen){$more.show();return}
const el=$text[0];const isTruncated=el.scrollWidth>el.clientWidth;$more.toggle(isTruncated)})}
updateTextExpandToggle();$(window).on('resize',updateTextExpandToggle);window.updateTextExpandToggle=updateTextExpandToggle;$(document).on('click','[data-text-expand-toggle]',function(e){e.preventDefault();const $item=$(this).closest('[data-text-expand-item]');$item.toggleClass('text-expand-open');$(this).text($item.hasClass('text-expand-open')?'Less':'More')});$(document).on('click','.slider-nav a',function(){const $openItems=$(this).closest('.slider').find('[data-text-expand-item].text-expand-open');if(!$openItems.length)return;$openItems.removeClass('text-expand-open');$openItems.find('[data-text-expand-toggle]').text('More');updateTextExpandToggle()});$(document).on('click','[data-text-expand-link-wrap]',function(e){if($(e.target).closest('a, [data-text-expand-toggle]').length)return;const href=$(this).data('href');if(!href)return;window.location.href=href})}
function initFeedAndLive(body,imageThumbLoader){initCaptchaPreloader();$('.ajax-preload').each(function(){let element=$(this);if(element.data('url')){rFetch({url:element.data('url'),success:function(response){element.html(response);updateTextExpandToggle();if(window.imageThumbLoader){window.imageThumbLoader.startLazyLoad()}}})}});if(window.gtag===undefined){window.gtag=()=>{}}
const videoLive=$('.video-splash.video-live');if(videoLive.length){new VideoImage(videoLive)}
const initLiveListItem=(el)=>{const $el=$(el);if($el.data('imgPlayer'))return;const inst=new VideoImage($el);$el.data('imgPlayer',inst);inst.stop()};const viewportBottom=$(window).scrollTop()+$(window).height();$('.video-splash.live-list').each(function(){const top=$(this).offset().top;if(top<=viewportBottom){initLiveListItem(this)}});$(window).on('scroll.liveList',function(){const bottom=$(window).scrollTop()+$(window).height();$('.video-splash.live-list').each(function(){const top=$(this).offset().top;if(top<=bottom){initLiveListItem(this)}})});$('.stop-propagation').click(function(e){e.stopPropagation()});let $liveActiveTouchEl=null;$(document).on('mouseenter','.video-splash.live-list',function(){initLiveListItem(this);const inst=$(this).data('imgPlayer');if(inst)inst.start();}).on('mouseleave','.video-splash.live-list',function(){const inst=$(this).data('imgPlayer');if(inst)inst.stop();}).on('touchstart','.video-splash.live-list',function(e){if($liveActiveTouchEl&&$liveActiveTouchEl[0]===this)return;e.preventDefault();if($liveActiveTouchEl){const prevInst=$liveActiveTouchEl.data('imgPlayer');if(prevInst)prevInst.stop();}
$liveActiveTouchEl=$(this);initLiveListItem(this);const inst=$(this).data('imgPlayer');if(inst)inst.start();});$(document).on('click','[data-back-button]',function(e){if(history.length>1){e.preventDefault();history.back()}})}